; The barrow. In at the bottom up the steps, through a short dark passage into the hall. The tomb
; is behind the locked door in the middle of the hall's north wall, and the side room is behind the
; stone door at its west end, which the lever at the east end works. Lit by the sconces (two either
; side of the tomb door), and a little daylight down the steps.

[map]
id = barrow
name = The Barrow
world = 860 110
tileset = crypt
size = 40 30
dark = yes
ambient = 0.07
music = Underground

[legend]
, = floor
w = floor-worn
s = floor-shadow
~ = steps
# = wall-top
F = wall-face
N = wall-niche
B = wall-base
r = rubble
b = bones
c = cobweb

