; kind id x y, in tiles, then any settings. A sconce or a lever goes on the lower row of a wall's
; face, and a door's foot is on the line where the face meets the floor.
[objects]
spawn start 19.5 27 facing=up
exit road 18 29 w=4 to=road at=barrow
light daylight 19.5 28.5 reach=3 strength=0.6
trigger cold 18 19 w=4 say="The air in here is colder."

prop sconce 8 13
prop sconce 17 13
prop sconce 22 13
prop sconce 28 13
prop sconce 19 3
prop sconce 6 7
prop sconce 23 25
prop sarcophagus 19.5 6.5
prop urn 10 15
prop urn 30 15
prop urn 16 5

door tomb 19.5 13.5 locked=yes name="Tomb door"
door side 4.5 13.5 look=gate flag=side-gate name="Stone door"
lever side-lever 30 13 flag=side-gate
chest side-chest 4.5 8 gold=40
